{
  "missing_information": [
    {
      "category": "Tool Selection Logic",
      "gap": "No criteria specified for how a particular measurement tool is selected for a given wafer",
      "why_it_matters": "Without knowing the selection logic, it is impossible to model the decision gateway that routes wafers to the correct tool, or to assess whether tool assignment can be automated"
    },
    {
      "category": "Tool-Specific Steps",
      "gap": "The preparation and measurement steps for each individual tool are not described",
      "why_it_matters": "Each tool variant represents a distinct process path; without step-level detail, the workflow cannot be reconstructed or analyzed for automation"
    },
    {
      "category": "Result Recording Method",
      "gap": "It is unclear how and where the engineer records the measurement result (e.g., paper log, spreadsheet, dedicated software system)",
      "why_it_matters": "The recording method determines whether this step is a candidate for automation and whether data is captured in a structured, machine-readable format"
    },
    {
      "category": "Acceptance Criteria and Outcomes",
      "gap": "No pass/fail or acceptance thresholds are defined for the measurement result",
      "why_it_matters": "Without outcome criteria, it is unknown what happens after recording—whether the wafer proceeds, is reworked, or is rejected—leaving the end of the process undefined"
    },
    {
      "category": "Roles and Responsibilities",
      "gap": "It is unclear whether only one engineer role is involved or whether technicians, equipment owners, or automated systems also participate",
      "why_it_matters": "Role clarity is required to assign process steps correctly and to identify which human tasks are candidates for automation or handoff"
    },
    {
      "category": "Triggers and Handoffs",
      "gap": "The event that initiates the workflow and how the wafer is handed off between steps or actors is not specified",
      "why_it_matters": "Without knowing the trigger and handoff mechanism, the start event and inter-step transitions cannot be modeled, and integration points for automation are unknown"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What determines which measurement tool is used for a given wafer—for example, is it based on wafer type, lot specification, tool availability, or some other criterion?",
      "targets": ["Tool Selection Logic"]
    },
    {
      "id": "Q2",
      "question": "Can you walk through the preparation and measurement steps for each tool variant, listing the distinct actions an operator must perform from the moment the wafer arrives at the tool until measurement is complete?",
      "targets": ["Tool-Specific Steps"]
    },
    {
      "id": "Q3",
      "question": "How does the engineer record the measurement result—what medium or system is used, and what data fields are captured at that point?",
      "targets": ["Result Recording Method"]
    },
    {
      "id": "Q4",
      "question": "What happens after the measurement result is recorded—are there defined thresholds or criteria that determine whether the wafer passes, is reworked, or is scrapped?",
      "targets": ["Acceptance Criteria and Outcomes"]
    },
    {
      "id": "Q5",
      "question": "Besides the engineer who records the result, which other roles or systems are involved in the workflow, and what actions are they responsible for?",
      "targets": ["Roles and Responsibilities"]
    },
    {
      "id": "Q6",
      "question": "What event triggers the start of this measurement workflow, and how is the wafer physically or informationally handed off between each step or actor?",
      "targets": ["Triggers and Handoffs"]
    }
  ]
}
